    // --- credential cap: refusal rolls back, expiry frees exactly one slot ---
    // A fresh flow, started under the current offset clock, so the 24h advance
    // above cannot expire it. Everything below is relative to that clock.
    const capStart = await startDevice({
      name: "local-cap-fellow",
      model: "test-model",
      harness: "codex",
      requested_scopes: ["review"],
    });
    const capStartBody = DeviceCodeStartResponseSchema.safeParse(
      parseLocalJson(await capStart.text()),
    );
    if (capStart.status !== 201 || !capStartBody.success) throw new Error("cap-device-start");
    const capCard = await post("/__s1/device-lookup", {
      sponsor_id: sponsorId,
      user_code: capStartBody.data.user_code,
    });
    if (capCard.status !== 200) throw new Error("cap-device-lookup");
    const capEnrollmentId = (parseLocalJson(await capCard.text()) as { card: { enrollment_id: string } })
      .card.enrollment_id;
    const capApprove = await post("/__s1/approve", {
      sponsor_id: sponsorId,
      enrollment_id: capEnrollmentId,
    });
    if (capApprove.status !== 200 && capApprove.status !== 201) throw new Error("cap-approve");

    const capSeed = await post("/__s1/local-only/credential-cap-seed", {
      flow_handle: capStartBody.data.device_code,
    });
    const capSeedBody = parseLocalJson(await capSeed.text()) as {
      seeded?: unknown;
      active?: unknown;
    };
    // 3/3 under the shipped predicate: the next insert is the fourth.
    if (capSeed.status !== 200 || capSeedBody.seeded !== 3 || capSeedBody.active !== 3) {
      throw new Error("cap-seed-boundary");
    }

    const capKey = "local-device-cap-poll-1";
    const capProof = async () =>
      parseLocalJson(
        await (
          await post("/__s1/local-only/credential-cap-proof", {
            flow_handle: capStartBody.data.device_code,
            idempotency_key: capKey,
          })
        ).text(),
      ) as Record<string, unknown>;
    const capBefore = await capProof();
    if (capBefore.proposal_status !== "approved" || capBefore.proposal_has_token !== 0) {
      throw new Error("cap-precondition");
    }

    const capRefused = await post(
      "/v1/device-token",
      { flow_handle: capStartBody.data.device_code },
      { "idempotency-key": capKey },
    );
    const capRefusedRaw = await capRefused.text();
    const capRefusedBody = parseLocalJson(capRefusedRaw) as { code?: unknown; status?: unknown };
    if (
      capRefused.status !== 409 ||
      capRefusedBody.code !== "FELLOW_CREDENTIAL_CAP_REACHED" ||
      capRefusedBody.status !== 409 ||
      capRefused.headers.get("cache-control") !== "no-store"
    ) {
      throw new Error("cap-refusal-face");
    }
    // Opaque: the refusal names capacity, never the SQL abort, the flow handle,
    // or any seeded credential.
    if (
      capRefusedRaw.includes("active credential cap reached") ||
      capRefusedRaw.includes(capStartBody.data.device_code)
    ) {
      throw new Error("cap-refusal-opacity");
    }
    // Whole-batch rollback through a real workerd D1 batch: neither the
    // proposal's token state nor any credential row nor the encrypted replay
    // row survived the trigger abort. Without this the exact retry below would
    // replay a 409 forever.
    const capAfterRefusal = await capProof();
    if (
      JSON.stringify(capAfterRefusal) !== JSON.stringify(capBefore) ||
      capAfterRefusal.poll_replay_rows !== 0 ||
      capAfterRefusal.credentials_from_proposal !== 0
    ) {
      throw new Error("cap-refusal-rollback");
    }

    const capAdvanced = await post("/__s1/local-only/advance-to-credential-expiry", {});
    if (capAdvanced.status !== 200) throw new Error("cap-expiry-advance");

    // Same key, same body. It must now succeed exactly once.
    const capIssued = await post(
      "/v1/device-token",
      { flow_handle: capStartBody.data.device_code },
      { "idempotency-key": capKey },
    );
    const capIssuedRaw = await capIssued.text();
    const capIssuedBody = parseLocalJson(capIssuedRaw) as { status?: unknown; token?: unknown };
    if (
      capIssued.status !== 200 ||
      capIssuedBody.status !== "approved" ||
      typeof capIssuedBody.token !== "string"
    ) {
      throw new Error("cap-expiry-retry");
    }
    const capAfterIssue = await capProof();
    if (
      capAfterIssue.proposal_has_token !== 1 ||
      capAfterIssue.credentials_from_proposal !== 1 ||
      capAfterIssue.poll_replay_rows !== 1
    ) {
      throw new Error("cap-expiry-issue-state");
    }

    // The bearer is crypto-random, so a recomputation could not reproduce these
    // bytes: byte-identity here proves the stored replay was served.
    const capReplay = await post(
      "/v1/device-token",
      { flow_handle: capStartBody.data.device_code },
      { "idempotency-key": capKey },
    );
    const capReplayRaw = await capReplay.text();
    if (capReplay.status !== 200 || capReplayRaw !== capIssuedRaw) {
      throw new Error("cap-replay-not-identical");
    }
    const capAfterReplay = await capProof();
    if (JSON.stringify(capAfterReplay) !== JSON.stringify(capAfterIssue)) {
      throw new Error("cap-replay-side-effect");
    }
    completeCase("mounted-device-cap-rollback-expiry-replay");

WHY THIS IS CAUSAL AND NOT A SECOND SHIM
- The bun:sqlite shim is not counted anywhere here. The dispatch is the local
  worker's existing fall-through, `createEnrollmentRouter({ service }).fetch(request)`
  (local-d1-worker.ts:490), with the service built on `new D1EnrollmentStore(env.DB)`
  where env.DB is the real workerd D1 binding from infra/wrangler.toml. Production
  router, production store, real Workerd, real shipped ladder.
- The refusal cannot be manufactured: there is no service-level active-credential
  pre-count in d1-store, and the only producer of FELLOW_CREDENTIAL_CAP_REACHED
  (d1-store:2474) is gated on the literal abort token that exactly one shipped
  trigger raises.
- The rollback assertion is total, not a sample: poll()'s entire write surface is
  enrollment_proposals, fellow_tokens and enrollment_idempotency, and the proof
  route reads all three. Every mutation on that path goes through `#db.batch`, so
  there is no out-of-transaction channel.
- Expiry polarity is load-bearing: seeding one credential at exactly
  now + STEP and advancing the clock by exactly STEP makes `expires_at > NEW.issued_at`
  false for that row and true for the other two. Invert the comparison and the
  seed assertion (3) and the retry both flip.
- Replay is causal because the token is crypto.getRandomValues-derived: a recompute
  emits a different token, so `capReplayRaw !== capIssuedRaw` is the only outcome
  a non-replaying implementation can produce.
- Failure cannot green the aggregate: the ledger rejects unknown, duplicate and
  out-of-order completions, and `cases()` throws evidence-case-incomplete unless
  all 34 declared cases completed in declared order. A throw anywhere above skips
  completeCase and the terminal record is never written.
- Local-only routes stay out of production: they live only in local-d1-worker.ts,
  which src/index.ts does not import, and each returns integers or a status enum
  behind the opaque flow-handle capability gate - no credential, hash, ciphertext,
  identifier or timestamp crosses the boundary.

